# -*- coding: utf-8 -*-
"""矛盾驱动补盲 · 批次C10（v8 新域 8 簇+直答）"""
def patch(path):
    src = open(path, encoding="utf-8").read()
    anchor_c = '    "概念形成": ["概念形成", "原型理论", "样例理论", "概念是怎么形成的"],'
    new_c = '''    "职场性别": ["职场天花板", "同工不同酬", "女性生孩子", "企业顾虑",
                "性别配额", "另一种不平等", "打破性别天花板", "性别平等",
                "职场女性", "女性晋升", "性别歧视", "职业女性"],
    "家务分工": ["家务总是女性", "全职主妇", "价值被低估", "男的赚钱养家",
                "女的管好家", "分工有错", "家务分工公平", "全职主妇价值",
                "全职主夫", "价值怎么衡量", "家务活", "带孩子"],
    "老年数字": ["老人用手机难", "不会扫码挂号", "老人怎么办", "老人懒得学",
                "数字时代淘汰", "跟不上的人", "跨越数字鸿沟", "人工窗口",
                "老人不会用", "扫码难", "老人手机", "数字鸿沟"],
    "教育就业": ["学的东西工作用不上", "专业不对口", "大学教思维", "学历贬值",
                "读书还有用", "选专业不后悔", "学历和能力", "学非所用",
                "专业和市场", "毕业找不到", "对口工作"],
    "网络暴力": ["网上骂人不用负责", "被网暴", "言论自由百无禁忌", "治理网络暴力",
                "网暴自救", "网络暴力", "网暴", "人肉搜索", "网络骂人",
                "键盘侠", "网暴受害者"],
    "心理求助": ["抑郁焦虑多", "心理问题矫情", "别人也难扛不住", "吃药有用",
                "需要心理帮助", "和抑郁的人相处", "抑郁症", "焦虑症",
                "心理健康", "心理医生", "心理咨询", "情绪崩溃"],
    "共享单车": ["共享单车乱", "到处都是乱的", "取消共享单车", "共享单车管",
                "共享经济", "乱停乱放", "共享电动车", "共享单车"],
    "城市养宠": ["遛狗不拴绳", "该不该罚", "狗是人类朋友", "拴着残忍",
                "怕狗的人矫情", "养宠共处", "城市养宠规范", "养狗",
                "狗叫扰民", "宠物粪便", "伤人"],'''
    assert anchor_c in src
    src = src.replace(anchor_c, new_c + "\n    " + anchor_c, 1)

    anchor_d = '    "概念形成": "概念形成是人获得概念的方式——原型理论（典型样例）、样例理论（具体实例）、理论观（嵌入知识网络）；对应知识卡组织",'
    new_d = '''    "职场性别": "职场对女性的天花板（晋升慢/薪酬低/产假顾虑），是『历史分工惯性』vs『现代平等』的矛盾——不是老板都坏，是制度默认了旧分工（男性养家女性顾家），女性一怀孕就『效率下降』成了潜规则。真相：①『女性要生孩子企业有顾虑』有现实成分——产假成本企业承担，但这是制度问题不是女性问题（社会该分担生育成本，不是企业压女性）；②同工不同酬确实存在——同样的岗位女性薪酬平均低（10-30%），部分是隐形（晋升慢导致），部分是直接（压价），这不是『市场定价』是『性别定价』；③性别配额是不是另一种不平等——争议真实：配额是『补偿性正义』（纠正历史不公），但选人不看能力看性别确实反公平，理想是『机会平等』（没有性别偏好），现实是『先配额纠正再取消』。打破天花板：①能力证明——用结果说话（业绩/项目），性别偏见挡不住硬成绩；②谈判意识——女性更容易接受低报价（社会训练的结果），学会谈薪酬/要资源；③制度——透明薪酬（公布同岗薪酬）/产假分担（男女同休降低企业顾虑）/反歧视法。性别平等的真公平：不是『一样』，是『机会一样+差异被尊重』——女性生育不该成为职业惩罚",
    "家务分工": "家务总是女性做、全职主妇价值被低估，是『家务劳动不可见』vs『价值衡量缺失』的矛盾——家务不产生工资（不上市交易），就被默认『没价值』，但做饭/带娃/打理家庭明明在创造价值（省下请保姆的钱/维持家庭运转）。真相：①『男的赚钱女的管家』分工有错吗——分工本身没错，错的是『价值不对等』：赚钱的觉得『我养你』（居高临下），管家的觉得『我付出不被看见』（委屈），健康的家庭是互相承认对方贡献（钱的贡献+劳动的贡献都算）；②全职主妇价值被低估——市场给不了工资，但换算成雇人成本（保姆+厨师+育儿嫂）月薪过万，『没工作』≠『没价值』；③『家务是小事计较矫情』——家务不是小事：它占时间/耗精力/且无休止（干完又乱），计较的不是活多少，是『对方看不看得见』。让分工公平：①家务清单化——把隐形劳动写出来（做饭/洗衣/带娃/人情/记账），看见是公平的第一步；②按偏好分——不是五五分，是『谁更受不了谁做』+ 置换（你做饭我洗碗）；③全职主妇/主夫的尊严——家庭财政透明（共同账户）、定期『换岗体验』（对方体会一下），价值在承认不在工资",
    "老年数字": "老人用手机难、不会扫码挂号，是『数字化提速』vs『老人学习减速』的矛盾——社会服务快速数字化（为效率），老人的学习速度/视力/记忆跟不上（为公平被牺牲）。真相：①老人用手机难不是懒——是多重障碍：视力差（字小看不清）、操作不熟悉（怕点错）、记忆衰退（学了这个忘那个）、恐惧（怕被骗不敢点），『多学学就会了』是年轻人视角，对80岁老人不现实；②『数字时代淘汰跟不上的人正常吗』——不正常：公共服务不是商业产品（商家可以只服务年轻人，政府不能只服务会用手机的人），把老人排除在挂号/办事之外是『制度性排斥』；③数字化的代价不该老人全扛——技术加速是趋势，但过渡期要有人工兜底。帮老人跨越鸿沟：①反哺教学——耐心教（一次一个功能/大字模式/写在纸上），老人学得慢但要的是『被教』不是『被嫌弃』；②适老设计——大字版APP/语音操作/简化流程（不是老人不行，是设计没为老人优化）；③人工兜底——医院/银行保留人工窗口/志愿者协助（服务所有人是底线，效率是优化不是替代）。核心：数字化要『等一等走不动的人』——效率重要，公平更重",
    "教育就业": "学的东西工作用不上、专业不对口，是『教育滞后』vs『市场变化』的矛盾——大学专业按几年前的需求设置（培养周期4年），市场变快了（行业兴衰/技能迭代），毕业时专业可能已过时。真相：①专业不对口正常吗——正常且普遍：多数人工作与专业不完全对口（约60%），因为大学教的是『学科基础+学习能力』，工作用的是『具体技能+经验』，跨专业是常态不是失败；②『大学教思维不是技能』——半真：文科/理科确实重思维（批判/逻辑），但技能型专业（医/工/法）不训练技能不行，理想是『思维+技能』结合，现实往往偏科；③学历贬值读书还有用吗——有用但用途变了：学历曾是『敲门砖』（有学历=好工作），现在是『入场券』（没学历连门都进不了，有学历只是基础），学历贬值的是『稀缺性』不是『价值』（读书提升的是学习能力/视野，这些永远有用）。选专业不后悔：①兴趣+能力+市场交集——喜欢（能坚持）×擅长（学得动）×有需求（毕业有饭吃），三个至少占两个；②看趋势不看热度——热门的（金融/计算机）毕业时可能饱和，选『需求增长』的（养老/健康/新能源）；③学历与能力——学历是起点，能力是过程，『学的东西用不上』时用得上的是『学会学习』的能力（任何新技能都能快速上手）",
    "网络暴力": "网上骂人不用负责、网暴频发，是『匿名性』vs『责任』的矛盾——网络匿名（没人认识我）+ 群体效应（大家都在骂）+ 执法难（跨平台/跨地域），骂人的成本极低，被骂的代价极高。真相：①为什么网上敢骂——三个放大器：匿名（不怕社死）、从众（法不责众/骂的是热点）、信息不全（只看到片段就开骂），现实中不敢说的话网上敢说，因为没后果；②『言论自由就该百无禁忌吗』——自由有边界：言论自由保护的是『表达观点』（我不同意你但捍卫你说话的权利），不保护『攻击人格』（辱骂/造谣/人肉是伤害不是言论）；③『网暴受害者活该吗』——活该论是二次伤害：网暴的惩罚远超过错（一个错误被放大万倍/牵连家人/人肉地址），『网暴正义』（替天行道）是私刑不是正义。治理网暴：①平台责任——实名追责（后台实名）/快速删评/反网暴机制（限流攻击性内容）；②法律——网暴入刑（诽谤/侵犯隐私已有法，执行要跟上）；③被网暴自救——截图取证（保留证据）、不回应（回应是燃料）、求助平台/警方/律师，必要时断网休息（先保护情绪再处理）；④旁观者——不做帮凶（不转发不评论）、可以举报（举报是低成本正义）",
    "心理求助": "抑郁焦虑的人越来越多、被当矫情，是『心理痛苦真实』vs『社会认知滞后』的矛盾——心理疾病是真实疾病（大脑化学/神经回路异常），但社会常当『想不开/矫情/意志薄弱』，患者被污名化→不敢求助→更严重。真相：①为什么现在抑郁焦虑多——三因素：压力变大（竞争/不确定）、认知提升（更多人认识心理问题→愿意承认/就医，过去是『忍忍就过去了』）、生活方式（屏幕/熬夜/久坐伤情绪），不全是『现在人脆弱』；②『心理问题是不是矫情』——不是：抑郁不是情绪不好（情绪不好过几天就好，抑郁是持续数周的功能损害），它像感冒发烧一样是身体状态异常，『别想太多』『坚强点』是安慰不了抑郁的（像对骨折的人说别疼）；③吃药有用吗——有用：重度抑郁靠药物（调节神经递质）+心理治疗（认知行为），药物不是『治标』是『治本手段之一』（像胰岛素之于糖尿病）。判断需不需要帮助：①信号——持续2周以上：情绪低落/失眠/食欲变/兴趣丧失/注意力下降；②影响——工作学习生活被影响（起不来床/不想见人）；③求助途径——先心理咨询（评估）再精神科（诊断），去医院不丢人。和抑郁的人相处：①不评判不劝『想开点』——陪伴比说教有用（『我在』比『别难过』有用）；②鼓励求助——陪TA去咨询/吃药（支持不是替代）；③照顾自己——陪伴抑郁者很耗心力，你也需要支持（别把自己搭进去）",
    "共享单车": "共享单车到处乱停，是『便利』vs『秩序』的矛盾——共享单车解决最后一公里（便宜/方便），但『随骑随停』=『随意乱停』（占道/堵路/影响市容），便利的代价是秩序的牺牲。真相：①为什么乱——商业模式使然：平台追求投放量（车越多用户越方便），管理跟不上（维护成本高/盈利薄），『方便』和『有序』是平台的两难（管严了不便利/不管则乱）；②『方便的时候不说，乱一点抱怨』——部分有理：共享单车利大于弊（减排/便利），乱停是管理问题不是『该不该有』的问题；③是不是该取消——不该：取消是倒退（回到自己买车/黑摩的），该做的是『规范』不是『消灭』。怎么管不乱：①电子围栏——规定停车区（APP标注，停外面加钱/无法还车），技术管比人管有效；②网格管理——平台按片负责（区域投放量/清运频次考核），乱停放直接影响区域配额；③用户约束——信用分（乱停扣分/涨价），让便利和信用挂钩。共享经济和城市秩序平衡：便利要有边界（你的方便不能堵别人的路），秩序要有弹性（别因噎废食）——技术和规则配合，共享才能可持续",
    "城市养宠": "城市养宠矛盾（吠叫/粪便/伤人），是『养宠自由』vs『他人安宁』的矛盾——宠物给主人陪伴和快乐，但噪音/卫生/安全由邻居共同承担（养宠的收益私人化，成本外溢）。真相：①遛狗不拴绳该不该罚——该：拴绳不是限制狗的『自由』，是保护它（跑丢/被车撞/打架）和保护别人（怕狗的人/小孩/老人），『我的狗不咬人』是主人错觉（动物有应激，谁也不敢保证）；②『狗是人类朋友拴着残忍』——拴绳不残忍（残忍的是放任不管让它出事），真正的爱是『既让狗快乐又不让它伤人』（用牵引绳/嘴套是负责任）；③『怕狗的人矫情』——不矫情：怕狗可能是被咬过（心理创伤）或单纯恐惧，怕狗者的安全感不该被养狗者的自由牺牲（就像抽烟者的自由止于不吸烟者的健康）。共处之道：①规矩先行——拴绳/清理粪便/疫苗/噪音控制（早晚时段注意），养宠自由以不扰民为前提；②互相理解——养宠者：邻居的抱怨不是针对你，是对行为；怕宠者：合理表达（别用毒杀/极端手段），投诉走正规渠道；③城市规范——遛狗时段/区域限制（公园分区）、伤人有责（主人赔偿）、流浪动物治理（源头绝育）。核心：养宠是权利也是责任——权利止于别人的安宁，责任始于拴绳和清理",
    "概念形成": "概念形成是人获得概念的方式——原型理论（典型样例）、样例理论（具体实例）、理论观（嵌入知识网络）；对应知识卡组织",'''
    assert anchor_d in src
    src = src.replace(anchor_d, new_d, 1)
    open(path, "w", encoding="utf-8").write(src)
    print("patched")

